 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture as tslTexture, uv as tslUV, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const group = new Group();
  group.name = config.id || 'pricing-card-1';

  const rect = config.atlasRegion || { x: 0, y: 0, w: 512, h: 320 };
  const aspect = rect.w / rect.h;

  const worldWidth = config.width || 2.0;
  const worldHeight = worldWidth / aspect;

  const geometry = new PlaneGeometry(worldWidth, worldHeight);
  const surfaceColor = config.intent?.visualSpec?.colors?.surface || '#0b0b10';
  const material = new MeshBasicNodeMaterial({ color: surfaceColor });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  let loadedTexture = null;

  mesh.onBeforeRender = function (renderer, scene, camera) {
    group.quaternion.copy(camera.quaternion);
  };

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      tex.colorSpace = THREE.SRGBColorSpace || THREE.SRGBEncoding;
      tex.wrapS = THREE.ClampToEdgeWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;

      const atlasW = tex.image?.width || rect.w;
      const atlasH = tex.image?.height || rect.h;

      const repeatX = rect.w / atlasW;
      const repeatY = rect.h / atlasH;
      const offsetX = rect.x / atlasW;
      const offsetY = rect.y / atlasH;

      const atlasUV = tslUV()
        .mul(vec2(repeatX, repeatY))
        .add(vec2(offsetX, offsetY));

      const texNode = tslTexture(tex, atlasUV);
      material.colorNode = texNode.rgb;
      material.opacityNode = texNode.a;
      material.transparent = true;
      material.alphaTest = 0.001;
      material.needsUpdate = true;
    });
  }

  group.userData.handlers = {};

  group.userData.cleanup = function () {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return group;
}
